### Create Custom State Schema with Node-Based State Updates in Workflow - Python and TypeScript

Source: https://github.com/langchain-ai/langgraph/blob/main/docs/docs/agents/context.md

Demonstrates defining a custom state schema with messages and additional fields for workflow graphs. Shows how nodes access the current state and return partial updates that modify specific state fields. The StateGraph API automatically merges node return values with the existing state, providing a clean pattern for state management across workflow execution.

```python
from typing_extensions import TypedDict
from langchain_core.messages import AnyMessage
from langgraph.graph import StateGraph

class CustomState(TypedDict):
    messages: list[AnyMessage]
    extra_field: int

def node(state: CustomState):
    messages = state["messages"]
    ...
    return {
        "extra_field": state["extra_field"] + 1
    }

builder = StateGraph(State)
builder.add_node(node)
builder.set_entry_point("node")
graph = builder.compile()
```

```typescript
import type { BaseMessage } from "@langchain/core/messages";
import { StateGraph, MessagesZodState, START } from "@langchain/langgraph";
import { z } from "zod";

const CustomState = z.object({
  messages: MessagesZodState.shape.messages,
  extraField: z.number(),
});

const builder = new StateGraph(CustomState)
  .addNode("node", async (state) => {
    const messages = state.messages;
    // ...
    return {
