### Build Stateful Workflows with LangGraph StateGraph (Python)

Source: https://context7.com/langchain-ai/langgraph/llms.txt

This Python code demonstrates the core principles of building stateful agent workflows using LangGraph's `StateGraph`. It covers defining a `TypedDict` for the graph's state, adding functional nodes, establishing fixed and conditional edges for flow control, and compiling the graph with an `InMemorySaver` for checkpointing. The example also shows how to invoke the compiled graph with a `thread_id` for conversation persistence.

```python
from typing import Annotated
from typing_extensions import TypedDict
from langgraph.graph import StateGraph, START, END
from langgraph.graph.message import add_messages
from langgraph.checkpoint.memory import InMemorySaver

# Define state schema with reducer function
class State(TypedDict):
    messages: Annotated[list, add_messages]
    user_info: str

# Create graph builder
graph_builder = StateGraph(State)

# Define node functions
def fetch_user_info(state: State):
    # Fetch user data
    return {"user_info": "User details from database"}

def chatbot(state: State):
    # Process with LLM
    response = llm.invoke(state["messages"])
    return {"messages": [response]}

def save_conversation(state: State):
    # Save to database
    print(f"Saving {len(state['messages'])} messages")
    return {}

# Add nodes to graph
graph_builder.add_node("fetch_user", fetch_user_info)
graph_builder.add_node("chatbot", chatbot)
graph_builder.add_node("save", save_conversation)

# Define conditional routing
def should_continue(state: State) -> str:
    last_message = state["messages"][-1]
    if hasattr(last_message, "tool_calls") and last_message.tool_calls:
        return "tools"
    return "save"

# Add edges: START -> fetch_user -> chatbot
graph_builder.add_edge(START, "fetch_user")
graph_builder.add_edge("fetch_user", "chatbot")

# Add conditional edge from chatbot
graph_builder.add_conditional_edges(
    "chatbot",
    should_continue,
    {"tools": "tools", "save": "save"}
)

# Add final edges
graph_builder.add_edge("save", END)

# Compile with checkpointer for persistence
memory = InMemorySaver()
graph = graph_builder.compile(checkpointer=memory)

# Execute with thread_id for conversation persistence
config = {"configurable": {"thread_id": "user-123"}}
result = graph.invoke(
    {"messages": [{"role": "user", "content": "Hello"}]},
    config=config
)

# Continue conversation in same thread
result = graph.invoke(
    {"messages": [{"role": "user", "content": "What did we discuss?"}]},
    config=config
)
```

